// Validate incoming perception + optional navigation
const data = items[0].json;

if (!data.perception) {
  return [{ json: { error: 'Missing perception data', status: 'error' } }];
}

// Validate perception against schema
const per = data.perception;
const requiredFields = ['scene_summary', 'objects', 'left_path', 'center_path', 'right_path', 'overall_risk', 'confidence'];
const missing = requiredFields.filter(k => !(k in per));
if (missing.length > 0) {
  return [{
    json: {
      error: 'Perception missing fields: ' + missing.join(', '),
      status: 'error',
      safe_action: 'WAIT',
      reason: 'Perception data incomplete',
      voice_instruction: 'Wait. Reassessing.',
      confidence: 0,
      timestamp: Date.now(),
    }
  }];
}

// Validate enums
const validRisks = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];
const validActions = ['LEFT', 'RIGHT', 'STRAIGHT', 'STOP', 'WAIT'];
const validPaths = ['left_path', 'center_path', 'right_path'];

for (const pk of validPaths) {
  if (per[pk]) {
    if (!validRisks.includes(per[pk].risk)) {
      return [{ json: { error: pk + '.risk invalid: ' + per[pk].risk, status: 'error' } }];
    }
  }
}

if (!validRisks.includes(per.overall_risk)) {
  return [{ json: { error: 'overall_risk invalid: ' + per.overall_risk, status: 'error' } }];
}

return [{
  json: {
    perception: per,
    navigation: data.navigation || null,
    session_id: data.session_id || 'unknown',
  }
}];

// Apply deterministic safety rules (mirrors server/safety_engine.py logic)

const perception = items[0].json.perception;
const navigation = items[0].json.navigation;
const now = Date.now();

const CONFIDENCE_THRESHOLD = 0.45;

// Helper: worst risk
const RISK_ORDER = { LOW: 0, MEDIUM: 1, HIGH: 2, CRITICAL: 3 };
function worstRisk(...risks) {
  const levels = risks.filter(r => r).map(r => RISK_ORDER[r]);
  if (levels.length === 0) return 'LOW';
  return Object.keys(RISK_ORDER).find(k => RISK_ORDER[k] === Math.max(...levels)) || 'LOW';
}

// Helper: risk from danger score
function riskFromScore(score) {
  if (score >= 0.85) return 'CRITICAL';
  if (score >= 0.65) return 'HIGH';
  if (score >= 0.40) return 'MEDIUM';
  return 'LOW';
}

// Analyze a path direction
function analyzePath(objects, direction) {
  const dirPrefix = direction.toLowerCase();
  let dangerScore = 0;
  const blocking = [];

  const typeDanger = {
    vehicle: 0.95, motorcycle: 0.90, bicycle: 0.70, person: 0.65,
    construction_barrier: 0.60, pole: 0.45, wall: 0.50, fence: 0.40,
    stairs: 0.55, curb: 0.30, pothole: 0.35, tree: 0.20, bench: 0.15,
    bin: 0.10, sign: 0.12, door: 0.18, animal: 0.50, unknown_obstacle: 0.40,
  };

  for (const obj of objects) {
    const position = (obj.position || '').toLowerCase();
    if (!position.startsWith(dirPrefix) && position !== direction) continue;

    const base = typeDanger[obj.type] || 0.30;
    let distMod = 0.5;
    if (obj.estimated_distance_m != null && obj.estimated_distance_m > 0) {
      const d = obj.estimated_distance_m;
      if (d < 2) distMod = 1.0;
      else if (d < 5) distMod = 0.8;
      else if (d < 10) distMod = 0.5;
    }
    if (obj.distance_confidence < 0.5) distMod *= 0.6;
    if (obj.blocks_path) base += 0.25;

    const objDanger = Math.min(base * distMod, 1);
    dangerScore = Math.max(dangerScore, objDanger);
    if (obj.blocks_path || objDanger >= 0.4) blocking.push(obj);
  }

  return {
    clear: dangerScore < 0.30 && blocking.length === 0,
    risk: riskFromScore(dangerScore),
    confidence: Math.min(1, blocking.length > 0 ? 0.5 + 0.1 * blocking.length : 0.85),
    blocking_objects: blocking,
  };
}

const objects = perception.objects || [];
const leftA = analyzePath(objects, 'left');
const centerA = analyzePath(objects, 'center');
const rightA = analyzePath(objects, 'right');

const perceptionConf = perception.confidence || 0;

// --- Low confidence check ---
if (perceptionConf < CONFIDENCE_THRESHOLD) {
  return [{ json: {
    action: 'WAIT',
    reason: 'Perception confidence (' + perceptionConf.toFixed(2) + ') below threshold (' + CONFIDENCE_THRESHOLD + '). Waiting.',
    confidence: perceptionConf,
    timestamp: now,
    perception_summary: { overall_risk: perception.overall_risk, primary_threat: 'low_confidence', threat_count: objects.length },
    voice_instruction: 'Wait. Reassessing.',
    debug: { rules_triggered: ['low_confidence'], safety_score: perceptionConf },
  }}];
}

// --- Vehicle immediate stop ---
const vehicleTypes = ['vehicle', 'motorcycle'];
const vehiclesInCenter = objects.filter(o =>
  vehicleTypes.includes(o.type) && (o.position || '').toLowerCase().startsWith('center')
);

for (const v of vehiclesInCenter) {
  const dist = v.estimated_distance_m;
  if (dist != null && dist < 8) {
    return [{ json: {
      action: 'STOP',
      reason: v.type + ' approaching at ~' + dist.toFixed(1) + 'm. Stopping for safety.',
      confidence: 0.95,
      timestamp: now,
      perception_summary: { overall_risk: 'CRITICAL', primary_threat: 'vehicle', threat_count: vehiclesInCenter.length },
      voice_instruction: 'Vehicle approaching. Stop.',
      debug: { rules_triggered: ['vehicle_immediate_stop'], safety_score: 0.95 },
    }}];
  }
  if (dist == null) {
    return [{ json: {
      action: 'STOP',
      reason: 'Vehicle in path (distance unknown). Stopping conservatively.',
      confidence: 0.80,
      timestamp: now,
      perception_summary: { overall_risk: 'HIGH', primary_threat: 'vehicle', threat_count: vehiclesInCenter.length },
      voice_instruction: 'Vehicle approaching. Stop.',
      debug: { rules_triggered: ['vehicle_unknown_distance_stop'], safety_score: 0.80 },
    }}];
  }
}

// --- Path selection ---
const paths = {
  LEFT: leftA,
  RIGHT: rightA,
  STRAIGHT: centerA,
};

function pathScore(analysis) {
  return [analysis.clear ? 0 : 1, RISK_ORDER[analysis.risk]];
}

const scored = Object.entries(paths)
  .map(([name, analysis]) => [name, pathScore(analysis), analysis])
  .sort((a, b) => {
    for (let i = 0; i < 2; i++) {
      if (a[1][i] !== b[1][i]) return a[1][i] - b[1][i];
    }
    return 0;
  });

const bestName = scored[0][0];
const bestAnalysis = scored[0][2];
const secondBest = scored.length > 1 ? scored[1][0] : null;

// --- All blocked ---
const allBlocked = Object.values(paths).every(p => !p.clear);
if (allBlocked && RISK_ORDER[perception.overall_risk] >= 2) {
  return [{ json: {
    action: 'STOP',
    reason: 'All paths blocked. Stopping.',
    confidence: 0.85,
    timestamp: now,
    perception_summary: { overall_risk: perception.overall_risk, primary_threat: describeBlockers(centerA.blocking_objects), threat_count: objects.length },
    voice_instruction: 'Path blocked. Stop.',
    debug: { rules_triggered: ['all_paths_blocked'], safety_score: RISK_ORDER[perception.overall_risk] },
  }}];
}

// --- Center blocked at high/critical ---
if (!centerA.clear && RISK_ORDER[centerA.risk] >= 2) {
  if (bestName === 'LEFT' || bestName === 'RIGHT') {
    const side = bestName.toLowerCase();
    const blockage = describeBlockers(centerA.blocking_objects) || 'hazard ahead';
    return [{ json: {
      action: bestName,
      reason: blockage + '. Safest path is ' + side + '.',
      confidence: bestAnalysis.confidence,
      timestamp: now,
      perception_summary: { overall_risk: perception.overall_risk, primary_threat: describeBlockers(objects.filter(o => o.risk === 'HIGH' || o.risk === 'CRITICAL')), threat_count: objects.length },
      navigation_context: navigation ? { current_step_instruction: navigation.route?.steps?.[navigation.route?.current_step_index || 0]?.instruction || '', remaining_steps: (navigation.route?.steps?.length || 0) - (navigation.route?.current_step_index || 0), next_turn: navigation.route?.steps?.[navigation.route?.current_step_index || 0]?.turn || null } : {},
      voice_instruction: blockage + '. Move ' + side + '.',
      debug: { rules_triggered: ['center_blocked'], safety_score: RISK_ORDER[perception.overall_risk], alternative_considered: secondBest },
    }}];
  }
}

// --- Straight clear ---
if (centerA.clear && centerA.risk === 'LOW') {
  return [{ json: {
    action: 'STRAIGHT',
    reason: 'Path ahead clear. Continue forward.',
    confidence: centerA.confidence,
    timestamp: now,
    perception_summary: { overall_risk: perception.overall_risk, primary_threat: describeBlockers(objects) || 'none', threat_count: objects.length },
    navigation_context: navigation ? { current_step_instruction: navigation.route?.steps?.[navigation.route?.current_step_index || 0]?.instruction || '', remaining_steps: (navigation.route?.steps?.length || 0) - (navigation.route?.current_step_index || 0), next_turn: navigation.route?.steps?.[navigation.route?.current_step_index || 0]?.turn || null } : {},
    voice_instruction: 'Path clear. Continue straight.',
    debug: { rules_triggered: ['path_clear'], safety_score: RISK_ORDER[perception.overall_risk] },
  }}];
}

// --- Best side path ---
if (bestName === 'LEFT' || bestName === 'RIGHT') {
  const side = bestName.toLowerCase();
  const blockage = describeBlockers(centerA.blocking_objects) || 'hazard ahead';
  return [{ json: {
    action: bestName,
    reason: blockage + '. Safest path is ' + side + '.',
    confidence: bestAnalysis.confidence,
    timestamp: now,
    perception_summary: { overall_risk: perception.overall_risk, primary_threat: describeBlockers(objects), threat_count: objects.length },
    navigation_context: navigation ? { current_step_instruction: navigation.route?.steps?.[navigation.route?.current_step_index || 0]?.instruction || '', remaining_steps: (navigation.route?.steps?.length || 0) - (navigation.route?.current_step_index || 0), next_turn: navigation.route?.steps?.[navigation.route?.current_step_index || 0]?.turn || null } : {},
    voice_instruction: blockage + '. Move ' + side + '.',
    debug: { rules_triggered: ['side_path'], safety_score: RISK_ORDER[perception.overall_risk], alternative_considered: secondBest },
  }}];
}

// --- Cautious straight ---
if (centerA.risk === 'LOW' || centerA.risk === 'MEDIUM') {
  return [{ json: {
    action: 'STRAIGHT',
    reason: 'Center path has ' + centerA.risk.toLowerCase() + ' risk. Proceed with caution.',
    confidence: centerA.confidence,
    timestamp: now,
    perception_summary: { overall_risk: perception.overall_risk, primary_threat: describeBlockers(objects) || 'low_risk_obstacle', threat_count: objects.length },
    voice_instruction: 'Path ahead. Continue with caution.',
    debug: { rules_triggered: ['cautious_straight'], safety_score: RISK_ORDER[centerA.risk] },
  }}];
}

// --- Fallback ---
return [{ json: {
  action: 'WAIT',
  reason: 'Unable to determine safe path. Waiting.',
  confidence: perceptionConf,
  timestamp: now,
  perception_summary: { overall_risk: perception.overall_risk, primary_threat: describeBlockers(objects), threat_count: objects.length },
  voice_instruction: 'Wait. Reassessing.',
  debug: { rules_triggered: ['fallback_wait'], safety_score: RISK_ORDER[perception.overall_risk] },
}}];

function describeBlockers(blockers) {
  if (!blockers || blockers.length === 0) return null;
  const types = [...new Set(blockers.map(b => b.type || 'obstacle'))].sort();
  if (types.length === 1) return types[0] + ' ahead';
  return types.join(' and ') + ' ahead';
}
